import test from 'node:test';import assert from 'node:assert/strict';
import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import {fileURLToPath} from 'node:url';import {build} from 'esbuild';
import {materializeBase} from '../../../../../desktop/godot/shared/materialize.mjs';
const bundled=await build({entryPoints:[fileURLToPath(new URL('../electron/main/creation-preview-service.ts',import.meta.url))],bundle:true,write:false,format:'esm',platform:'node'});
const {createCreationPreviewService,validateCreationPreview}=await import(`data:text/javascript;base64,${Buffer.from(bundled.outputFiles[0].text).toString('base64')}`);
const root=fileURLToPath(new URL('../../../../../',import.meta.url)),temporary=fs.mkdtempSync(path.join(os.tmpdir(),'creation-preview-service-'));
test.after(()=>fs.rmSync(temporary,{recursive:true,force:true}));
const manifest=materializeBase({baseId:'creation-sandbox',worldId:'preview-source',out:path.join(temporary,'source'),enginePerformanceProfile:'engine-monitor/1'});
const input={sessionId:'session-a',captureId:'capture-a',previewId:'preview-a',sequence:1,action:'place',kind:'tree',position:[4,0,4],scale:[1,1,1],rotationY:45,color:'#abcdef'};
function fixture(){const calls=[],capture={worldId:'world-a',buildId:'build-a',instanceId:'instance-a',sourceRevision:1,target:{surface:'ground',entityId:null},source:'ray'};let reads=0;const source={...structuredClone(manifest),worldId:'world-a',buildId:'build-a',sourceRevision:1,baseId:'creation-sandbox'};const deps={resourcesRoot:path.join(root,'desktop/godot'),capture:async(owner,session,id)=>{assert.equal(owner,1);assert.equal(session,input.sessionId);assert.equal(id,input.captureId);reads++;return structuredClone(capture);},source:async()=>structuredClone(source),dispatch:async(identity,args)=>{calls.push({identity,args});return {status:args.action==='cancel'?'cancelled':'visible',valid:true};}};return {deps,capture,source,calls,service:()=>createCreationPreviewService(deps),reads:()=>reads};}
test('preview uses scoped source/instance identity and never starts a source operation',async()=>{const f=fixture(),service=f.service();const before=structuredClone(f.source);assert.equal((await service.request(1,input)).status,'visible');assert.equal(f.reads(),3);assert.deepEqual(f.calls[0].identity,{worldId:'world-a',buildId:'build-a',instanceId:'instance-a'});assert.equal(f.calls[0].args.kind,'tree');assert.deepEqual(f.source,before);});
test('preview rejects coordinate/identity injection and all unbounded transforms',()=>{for(const patch of [{worldId:'other'},{action:'delete'},{rotationY:181},{position:[0,-1,0]},{scale:[1,5,1]},{sequence:0.5},{color:'red'}])assert.throws(()=>validateCreationPreview({...input,...patch}),/INVALID/);});
test('cancel retires the exact token and late updates cannot resurrect it',async()=>{const f=fixture(),service=f.service();await service.request(1,input);await service.request(1,{sessionId:input.sessionId,captureId:input.captureId,previewId:input.previewId,sequence:2,action:'cancel'});await assert.rejects(service.request(1,{...input,sequence:3}),/SUPERSEDED/);assert.equal(f.calls.filter(c=>c.args.action==='place').length,1);assert.equal(f.calls.at(-1).args.action,'cancel');});
test('new preview clears previous token while a late old cancel cannot clear the new one',async()=>{const f=fixture(),service=f.service();await service.request(1,input);await service.request(1,{...input,previewId:'preview-b'});const count=f.calls.length;await service.request(1,{sessionId:input.sessionId,captureId:input.captureId,previewId:'preview-a',sequence:8,action:'cancel'});assert.equal(f.calls.length,count);assert.deepEqual(f.calls.map(c=>c.args.action),['place','cancel','place']);});
test('retained custom stock generator and source aliases are not fabricated into previews',async()=>{for(const mutate of [source=>source.files.find(f=>f.path==='scripts/creation_world.gd').sha256='a'.repeat(64),source=>source.files.push({...source.files.find(f=>f.path==='scripts/creation_world.gd'),path:'SCRIPTS/CREATION_WORLD.GD'}),source=>source.sourceRevision++]){const f=fixture();mutate(f.source);await assert.rejects(f.service().request(1,input),/SOURCE_UNSUPPORTED|TARGET_STALE/);assert.equal(f.calls.length,0);}});
test('recent object selection cannot authorize a new ground placement',async()=>{const f=fixture();f.capture.source='recent';await assert.rejects(f.service().request(1,input),/GROUND_REQUIRED/);assert.equal(f.calls.length,0);});
test('stale capture at response boundary clears the just-created ghost and returns no success',async()=>{const f=fixture(),original=f.deps.capture;f.deps.capture=async(...args)=>{if(f.calls.some(c=>c.args.action==='place'))throw Error('CREATION_TARGET_STALE');return original(...args);};await assert.rejects(f.service().request(1,input),/TARGET_STALE/);assert.deepEqual(f.calls.map(c=>c.args.action),['place','cancel']);});
test('modify derives target from host capture and rejects replay sequences',async()=>{const f=fixture();f.capture.target={surface:'entity',entityId:'tree-owned'};const service=f.service(),request={...input,action:'modify'};delete request.kind;await service.request(1,request);assert.equal(f.calls[0].args.targetId,'tree-owned');await assert.rejects(service.request(1,request),/SUPERSEDED/);});
